/// Encapsulate to a public U8 key. Canonicality is checked on device.
/// # Errors
/// Rejects key dtype/owner/extent, capture, entropy, or execution errors.
pub fn mlkem_encapsulate(
	public_key: &Matrix,
	parameters: MlKemParameters,
) -> Result<DeviceEncapsulation> {
	if public_key.num_elements() != parameters.public_key_size() {
		return Err(Error::invalid_argument("ML-KEM public key extent mismatch"));
	}
	let (inner, ciphertext, status, cleanup) = public_key.engine_handle().pqc_mlkem_encapsulate(
		parameters.k(),
		public_key,
		Entropy::generate()?,
	)?;
	Ok(DeviceEncapsulation {
		shared_secret: DeviceSharedSecret { inner },
		ciphertext,
		status,
		cleanup: DeviceErasure { inner: cleanup },
	})
}

